WITH store_qty AS ( SELECT ss_item_id AS i_item_id, SUM(ss_quantity) AS store_quantity FROM store_sales GROUP BY ss_item_id ), web_qty AS ( SELECT ws_item_id AS i_item_id, SUM(ws_quantity) AS web_quantity FROM web_sales GROUP BY ws_item_id ), review_stats AS ( SELECT pr_item_id AS i_item_id, AVG(pr_sentiment) AS avg_sentiment, COUNT(*) AS review_count FROM product_reviews GROUP BY pr_item_id ) SELECT i.i_item_id, i.i_name, i.i_category, COALESCE(sq.store_quantity, 0) AS store_quantity, COALESCE(wq.web_quantity, 0) AS web_quantity, COALESCE(sq.store_quantity, 0) + COALESCE(wq.web_quantity, 0) AS total_quantity, rs.avg_sentiment, rs.review_count FROM items i LEFT JOIN store_qty sq ON sq.i_item_id = i.i_item_id LEFT JOIN web_qty wq ON wq.i_item_id = i.i_item_id LEFT JOIN review_stats rs ON rs.i_item_id = i.i_item_id ORDER BY total_quantity DESC LIMIT 10
